import{_ as t,o,c as i,a2 as a}from"./chunks/framework.CHeM0PsO.js";const g=JSON.parse('{"title":"Gemini 手部与进食特写","description":"","frontmatter":{},"headers":[],"relativePath":"tools/gemini-hands-eating.md","filePath":"tools/gemini-hands-eating.md","lastUpdated":1787456457000}'),n={name:"tools/gemini-hands-eating.md"};function s(l,e,r,c,d,p){return o(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="gemini-手部与进食特写" tabindex="-1">Gemini 手部与进食特写 <a class="header-anchor" href="#gemini-手部与进食特写" aria-label="Permalink to &quot;Gemini 手部与进食特写&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">来源</p><ul><li>来源：Gemini Web（Google Gemini）现场问答</li><li>时间：2026-08-15</li><li>说明：本文为用户向 Gemini Web 提问拿到的回答，仅做排版整理，文字未做改写。内容由 Gemini 生成，未经 Google 官方文档逐一核实；涉及 Veo 对手部/口腔的解算能力请以官方文档为准。</li></ul></div><blockquote><p>提问：手拿薯条、牙齿咬断、食物入口这类特写，手指 / 牙齿 / 口腔细节最容易崩，怎么在 prompt 里约束才稳定？</p></blockquote><h2 id="核心策略" tabindex="-1">核心策略 <a class="header-anchor" href="#核心策略" aria-label="Permalink to &quot;核心策略&quot;">​</a></h2><p>手指、牙齿、舌头、口腔属于高维关节与复杂物理碰撞区域，是扩散模型最容易「融化、多指、多齿、形变」的重灾区。核心策略：<strong>用强物理约束锁定运动幅度 + 降低解算复杂度 + 避开微观口腔解算</strong>。</p><h2 id="三大崩溃点的约束法则" tabindex="-1">三大崩溃点的约束法则 <a class="header-anchor" href="#三大崩溃点的约束法则" aria-label="Permalink to &quot;三大崩溃点的约束法则&quot;">​</a></h2><p><strong>1. 手持薯条（防多指 / 融化）</strong></p><ul><li>明确手部姿势：不写 <code>holding a french fry</code>，写 <code>thumb and index finger</code>（食指拇指捏住）。</li><li>锁定手指数量与状态：写 <code>two fingers only</code> 或 <code>thumb and index finger visible</code>。</li><li>加景深：把手和薯条置于焦平面，背景拉虚，逼模型把像素算力集中到手和薯条上。</li></ul><p><strong>2. 牙齿咬断（防齿数混乱 / 咬合错误）</strong></p><ul><li>锁定牙齿局部：写 <code>front teeth</code>（门牙）或 <code>upper teeth</code>（上排），别让模型生成整张嘴的复杂齿列。</li><li>控制运动幅度：用「预咬」或「接触即止」，别写大跨度咬合全过程。</li><li>用物理碎屑转移注意力：显式写「断裂声响的视觉化」，既增加真实感又掩盖齿部解算不稳。</li></ul><p><strong>3. 食物入口（防口腔黑洞 / 肌肉融化）</strong></p><ul><li>避拍深层口腔：不写 <code>tongue chewing</code>、<code>inside the mouth</code>。</li><li>用唇部掩护：焦点放在「嘴唇张开 → 咬下 → 唇角微扬」。</li></ul><h2 id="实战-prompt-拆解" tabindex="-1">实战 Prompt 拆解 <a class="header-anchor" href="#实战-prompt-拆解" aria-label="Permalink to &quot;实战 Prompt 拆解&quot;">​</a></h2><p><strong>手持薯条特写</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Extreme close-up shot, macro video. Two clean, photorealistic fingers (thumb and index finger) holding a single golden crispy french fry coated with honey butter seasoning. The camera captures ultra-detailed crisp texture and tiny seasoning crystals. Shallow depth of field, soft natural studio lighting, 8k resolution, photorealistic, high-end food commercial style, slow motion 60fps.</span></span></code></pre></div><p>关键约束：<code>Two clean, photorealistic fingers (thumb and index finger)</code> 锁死两根手指，减少多指概率。</p><p><strong>牙齿咬断薯条</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Macro slow-motion close-up. Pristine upper front teeth taking a clean bite out of a thick-cut tomato-flavored french fry. The fry snaps precisely in half with tiny crunchy crumbs scattering in mid-air. Macro lens, sharp focus on the teeth and fry, soft lip framing, backlit, clean commercial lighting, cinematic 4k food ad.</span></span></code></pre></div><p>关键约束：<code>Pristine upper front teeth</code>（只渲染上排门牙）、<code>snaps precisely in half</code>（明确断成两半，避免橡胶化拉丝）、<code>crumbs scattering</code>（碎屑掩盖缝隙失真）。</p><p><strong>食物送入口中</strong></p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Side-profile close-up shot. Soft natural lips gently open as a golden french fry is brought towards the mouth. Natural facial movement, clean skin texture, realistic lighting, warm aesthetic. Shot on 35mm lens, depth of field, high-end snack advertisement.</span></span></code></pre></div><p>关键约束：<code>Side-profile</code>（斜侧角度比正对嘴稳定 80% 以上，避开口腔内部解算）。</p><h2 id="禁用词与运镜技巧" tabindex="-1">禁用词与运镜技巧 <a class="header-anchor" href="#禁用词与运镜技巧" aria-label="Permalink to &quot;禁用词与运镜技巧&quot;">​</a></h2><p><strong>绝对避开</strong>：<code>tongue chewing</code>、<code>inside the mouth</code>、<code>full mouth open</code>、<code>hand holding a handful of fries</code>（手抓一把必融合）。</p><p><strong>运镜</strong>：静态镜头（<code>Static Shot</code>）或极微前移（<code>Slow Push-in</code>）——咬断本身已有动态，镜头再快动会双重运动导致解算崩溃；<code>Slow Motion / 60fps / 120fps</code> 能掩盖肌肉/咬合接缝的不自然滑移。</p><p><strong>工作流</strong>：先出「手持/咬下」的高清剧照做首帧，再驱动 2 秒动作（成功率 90%+）；成片里咬断特写只用 0.5–1.2 秒，截取最准的 10–20 帧配「咔嚓」音效即可。</p><hr><p>关联：手部/口腔的形变崩坏靠首帧锁定兜底，见 <a href="/tools/gemini-first-last-frame">首帧与首尾帧锁定</a>；静态镜头降崩溃见 <a href="/tools/gemini-camera-failsafe">运镜翻车词</a>；<code>deformed hands</code> 等负面词见 <a href="/tools/gemini-negative-tokens">排除项写法</a>。</p>',28)])])}const u=t(n,[["render",s]]);export{g as __pageData,u as default};
